'use strict';
(()=>{if(!window.PK_CONFIG?.enabled)return;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icon=(name)=>{const p={swords:'M4 3l7 7-3 3-6-7 2-3Zm16 0-7 7 3 3 6-7-2-3ZM3 21l6-6m-6 0 6 6m12 0-6-6m0 6 6-6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-3.9M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 7',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0V5Zm-3 6v1a6 6 0 0 0 12 0v-1m-6 7v4m-4 0h8',chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z',trophy:'M8 3h8v6a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v7m-4 1h8',arrow:'M4 12h16m-6-6 6 6-6 6',copy:'M8 8h12v13H8V8ZM4 16H2V2h12v2',close:'m6 6 12 12M18 6 6 18'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[name]||p.swords}"/></svg>`;};
 let user=null,room=null,socket=null,code='',busy=false,error='',draft='',voiceExpanded=false,reconnectTimer=0,retries=0,clockOffset=0,profileAvatar=null,profileOpen=false;
 const voice=new window.KienBattleVoice(send,notice),titles={history:'Lịch sử Đảng',information:'Lý thuyết truyền tin',ai:'Khoa học dữ liệu & AI'};
 async function api(path,body){if(!window.PK_CONFIG.preview){if(path==='/session'&&!window.KienCloud.getUser())return {user:null};return window.KienCloud.api('/pk'+path,body,true);}const r=await fetch('/api/pk'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Không kết nối được phòng.');return d;}
 function notice(text){error=text;const el=document.querySelector('#pk-notice');if(el){el.textContent=text;el.hidden=!text;}else window.KienUI?.toast?.(text);}
 function avatar(p,cls=''){const initials=p.name?.trim().split(/\s+/).slice(-2).map(w=>w[0]).join('').toUpperCase()||'KH',tone=[...p.id].reduce((a,c)=>a+c.charCodeAt(0),0)%6;return `<span class="pk-avatar pk-tone-${tone} ${cls}" data-pk-peer="${esc(p.id)}">${p.avatar?`<img src="${esc(p.avatar)}" alt="" width="48" height="48">`:(window.KienPKAvatar?window.KienPKAvatar(p.id):`<span aria-hidden="true">${esc(initials)}</span>`)}</span>`;}
 function landing(){return `<div class="pk-landing"><section class="pk-intro pk-glass"><span class="pk-kicker">HỌC CÙNG NHAU. TIẾN XA HƠN.</span><h2>Một phòng nhỏ.<br><em>Một cuộc đua kiến thức.</em></h2><p>Rủ nhóm bạn vào cùng một đề quiz. Sẵn sàng, khóa đáp án và xem ai chinh phục nhiều câu hỏi nhất.</p><div class="pk-features"><span>${icon('users')} 2–8 người</span><span>${icon('chat')} Chat trực tiếp</span><span>${icon('mic')} Voice tùy chọn</span></div><ol class="pk-steps"><li><b>01</b><span>Tạo phòng hoặc nhập mã</span></li><li><b>02</b><span>Cùng sẵn sàng, cùng bắt đầu</span></li><li><b>03</b><span>Trả lời, tranh hạng, cùng ghi nhớ</span></li></ol></section><div class="pk-entry"><section class="pk-glass pk-profile-box"><div><span class="pk-kicker">BẠN SẼ XUẤT HIỆN VỚI</span><h3>${user?esc(user.name):'Một danh tính của riêng bạn'}</h3><p>${window.PK_CONFIG.preview?'Hồ sơ thử riêng; không cần email hay mật khẩu thật.':'Dùng tên và avatar trong mục cá nhân hóa.'}</p></div>${user?avatar(user):'<span class="pk-avatar pk-tone-2">KH</span>'}<button class="btn" type="button" data-pk-profile>${user?(window.PK_CONFIG.preview?'Chỉnh hồ sơ thử':'Chỉnh hồ sơ'):(window.PK_CONFIG.preview?'Tạo hồ sơ thử':'Đăng nhập để tham gia')}</button></section><section class="pk-glass"><h3>${icon('swords')} Tạo một cuộc tranh đấu</h3><form id="pk-create"><label for="pk-subject">Môn thi<select id="pk-subject" name="subject"><option value="history">Lịch sử Đảng</option><option value="information">Lý thuyết truyền tin</option><option value="ai">Khoa học dữ liệu & AI</option></select></label><div class="pk-form-pair"><label for="pk-count">Số câu<select id="pk-count" name="count"><option value="5">5 câu · khởi động</option><option value="10" selected>10 câu</option><option value="20">20 câu</option></select></label><label for="pk-seconds">Mỗi câu<select id="pk-seconds" name="seconds"><option value="15">15 giây</option><option value="20" selected>20 giây</option><option value="30">30 giây</option><option value="45">45 giây</option></select></label></div><button class="btn primary pk-wide" ${busy?'disabled':''}>Tạo phòng ${icon('arrow')}</button></form></section><section class="pk-glass"><h3>Bạn có mã mời?</h3><form id="pk-join" class="pk-join-form"><label class="sr-only" for="pk-code">Mã phòng gồm 6 ký tự</label><input id="pk-code" name="code" maxlength="6" pattern="[A-Za-z2-9]{6}" placeholder="VD: HOC8K2" value="${esc(code)}" required autocomplete="off"><button class="btn" ${busy?'disabled':''}>Vào phòng ${icon('arrow')}</button></form></section></div></div><div class="pk-rules-note">${icon('trophy')} Mỗi đáp án đúng được 1.000 điểm + tối đa 500 điểm tốc độ. Thời gian và điểm do máy chủ tính. Chỉ dùng câu có một đáp án rõ ràng; kết quả mang tính luyện tập.</div>`;}
 function roster(){return `<div class="pk-roster-heading"><div><span class="pk-kicker">ĐỒNG ĐỘI & ĐỐI THỦ</span><h3>${room.players.filter(p=>!p.left).length} / 8 người trong phòng</h3></div><div class="pk-avatar-group">${room.players.filter(p=>!p.left).map(p=>`<span class="pk-avatar-hover" tabindex="0" aria-label="${esc(p.name)}${p.id===room.host?' · Chủ phòng':''}">${avatar(p)}<span class="pk-avatar-tip">${esc(p.name)}</span></span>`).join('')}</div></div><div class="pk-people">${room.players.filter(p=>!p.left).sort((a,b)=>a.id===room.host?-1:b.id===room.host?1:0).map(p=>`<div class="pk-person ${p.id===user.id?'is-you':''}">${avatar(p)}<div><b>${esc(p.name)} ${p.id===user.id?'<small>Bạn</small>':''}</b><span>${p.id===room.host?'Chủ phòng · ':''}${!p.online?'Đang kết nối lại':p.ready?'Đã sẵn sàng':'Đang chuẩn bị'}</span></div><span class="pk-presence ${p.online?'on':''}"></span>${room.host===user.id&&p.id!==user.id&&room.phase==='lobby'?`<button class="pk-icon-btn" aria-label="Mời ${esc(p.name)} rời phòng" data-pk-kick="${esc(p.id)}">${icon('close')}</button>`:''}</div>`).join('')}</div>`;}
 function chat(){
  const runs=[];for(const m of room.chat){const last=runs.at(-1);if(last?.[0].userId===m.userId)last.push(m);else runs.push([m]);}
  const members=room.players.filter(p=>!p.left);
  return `<section class="pk-glass pk-chat"><div class="pk-panel-heading"><h3>${icon('chat')} Cuộc trò chuyện</h3><span class="pk-live-dot">${socket?.readyState===1?'Trực tiếp':'Đang kết nối'}</span></div><div class="pk-chat-members"><span># ${room.code}</span><div class="pk-avatar-group" aria-hidden="true">${members.slice(0,4).map(p=>avatar(p)).join('')}${members.length>4?'<small>+'+(members.length-4)+'</small>':''}</div></div><div class="pk-messages" id="pk-messages" role="log" aria-label="Tin nhắn trong phòng" aria-live="polite">${runs.length?runs.map(run=>{const m=run[0],person=room.players.find(p=>p.id===m.userId)||{id:m.userId,name:m.name};return `<article class="pk-message pk-chat-run ${m.userId===user.id?'mine':''}">${avatar(person)}<div class="pk-chat-run-body"><div class="pk-chat-author"><b>${esc(person.name)}</b><time>${new Date(m.at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</time></div>${run.map(message=>`<p>${esc(message.text)}</p>`).join('')}</div></article>`;}).join(''):'<div class="pk-chat-empty">Một lời chào trước khi bắt đầu?<small>Tin nhắn chỉ dành cho thành viên phòng này.</small></div>'}</div><form id="pk-chat-form"><label class="sr-only" for="pk-message">Tin nhắn</label><input id="pk-message" name="message" placeholder="Nhắn một điều cho cả phòng…" maxlength="500" autocomplete="off" value="${esc(draft)}"><button class="pk-icon-btn" aria-label="Gửi tin nhắn" ${socket?.readyState!==1?'disabled':''}>${icon('arrow')}</button></form><small>Không gửi thông tin nhạy cảm. Tối đa 500 ký tự / tin.</small></section>`;
 }

 function voiceWidget(){const people=room.players.filter(p=>p.voice&&p.online&&!p.left);return `<section class="pk-voice pk-glass ${voiceExpanded?'expanded':''}"><button class="pk-voice-head" data-pk-voice-expand aria-expanded="${voiceExpanded}" aria-controls="pk-voice-content">${icon('mic')}<b>Voice cùng nhóm</b><span>${people.length} người</span><span class="pk-wave" aria-hidden="true"><i></i><i></i><i></i><i></i></span></button><div id="pk-voice-content" ${voiceExpanded?'':'hidden'}><div class="pk-voice-grid">${people.length?people.map(p=>`<div>${avatar(p)}<b>${esc(p.name)}</b><small>${p.muted?'Đang tắt mic':'Mic đang bật'}</small></div>`).join(''):'<p>Chưa ai vào voice.<br>Bạn có thể là người bắt đầu.</p>'}</div>${voice.stream?`<div class="pk-voice-actions"><button class="btn" data-pk-mute aria-pressed="${voice.muted}">${voice.muted?'Bật micro':'Tắt micro'}</button><button class="btn" data-pk-listen>Nghe âm thanh</button><button class="btn" data-pk-voice-leave>Rời voice</button></div>`:`<button class="btn primary pk-wide" data-pk-voice-join ${socket?.readyState!==1?'disabled':''}>${icon('mic')} Tham gia voice</button>`}<small>Micro tắt khi mới vào. Không ghi âm. ${voice.stream&&!voice.relay?'Kết nối trực tiếp · có thể hạn chế giữa hai mạng khác nhau.':''}</small></div></section>`;}
 function quiz(){const q=room.question,remaining=Math.max(0,Math.ceil((room.deadline-(Date.now()+clockOffset))/1000)),starting=Date.now()+clockOffset<room.roundStart;return `<section class="pk-glass pk-question"><div class="pk-round-top"><span class="pk-kicker">CÂU ${room.round+1} / ${room.total}</span><span class="pk-timer" id="pk-time" role="timer">${starting?'Chuẩn bị…':remaining+'s'}</span></div><div class="pk-round-track"><i style="width:${(room.round+1)/room.total*100}%"></i></div><h2 tabindex="-1" id="pk-question-title">${esc(q.question)}</h2><div class="pk-options">${q.options.map((option,i)=>`<button type="button" data-pk-answer="${'ABCD'[i]}" class="pk-answer ${room.myChoice==='ABCD'[i]?'selected':''}" ${room.myChoice||starting||remaining===0?'disabled':''}><b>${'ABCD'[i]}</b><span>${esc(option)}</span>${room.myChoice==='ABCD'[i]?'<small>Đã khóa</small>':''}</button>`).join('')}</div><p class="pk-lock-note" role="status">${room.myChoice?'Bạn đã khóa đáp án '+room.myChoice+'. Chờ cả phòng sang câu kế tiếp.':'Chọn một lần. Đáp án được khóa ngay khi máy chủ nhận.'}</p><div class="pk-answer-presence">${room.players.filter(p=>!p.left).map(p=>`<span class="${p.answered?'done':''}">${avatar(p)}<small>${p.answered?'Đã trả lời':'Đang nghĩ'}</small></span>`).join('')}</div></section>`;}
 function results(){const ranked=room.players.filter(p=>!p.left).sort((a,b)=>a.rank-b.rank),winners=ranked.filter(p=>p.rank<=3);return `<section class="pk-glass pk-results"><span class="pk-kicker">MỖI LƯỢT ĐẤU. MỘT BƯỚC TIẾN.</span><h2>Vinh danh những người dẫn đầu.</h2><p>${titles[room.settings.subject]} · ${room.total} câu · Kết quả lượt này</p><div class="pk-podium">${[2,1,3].map(rank=>{const p=winners.find(p=>p.rank===rank);return `<div class="pk-podium-place place-${rank}">${p?`${rank===1?`<span class="pk-crown">${icon('trophy')}</span>`:''}${avatar(p)}<b>${esc(p.name)}</b><strong data-count-id="pk-${room.code}-${p.id}" data-count-to="${p.score}">${p.score}</strong><span>${p.correct} câu đúng</span><div class="pk-pedestal"><b>0${rank}</b></div>`:'<span class="pk-unranked">Chưa có hạng '+rank+'</span>'}</div>`;}).join('')}</div><div class="pk-ranking-table"><div class="pk-ranking-label"><span>Hạng / Thành viên</span><span>Đúng / Điểm</span></div>${ranked.map(p=>`<div class="pk-ranking-row ${p.id===user.id?'is-you':''}"><span class="pk-rank">${p.rank}</span>${avatar(p)}<b>${esc(p.name)}${p.id===user.id?' · Bạn':''}</b><span>${p.correct} / ${room.total}<strong>${new Intl.NumberFormat('vi-VN').format(p.score)}</strong></span></div>`).join('')}</div><small>Ưu tiên điểm, sau đó tổng thời gian trả lời. Đồng điểm và thời gian được đồng hạng. Người bỏ cuộc khi đang thi không được xếp hạng.</small>${room.host===user.id?'<button class="btn primary" data-pk-rematch>Đấu lại bộ câu này →</button>':''}<details class="pk-review"><summary>Xem lại câu hỏi & lời giải</summary>${room.review.map((q,i)=>`<article><span class="pk-kicker">CÂU ${i+1}</span><h3>${esc(q.question)}</h3><p>Bạn chọn: ${esc(q.mine||'Chưa chọn')} · Đáp án: ${q.answers.join(', ')}</p><p>${esc(q.options['ABCD'.indexOf(q.answers[0])])}</p><p>${esc(q.explanation)}</p></article>`).join('')}</details></section>`;}
 function roomView(){const mine=room.players.find(p=>p.id===user.id);return `<div class="pk-room-top"><div><span class="pk-kicker">${room.phase==='lobby'?'PHÒNG CHỜ':room.phase==='finished'?'ĐÃ HOÀN THÀNH':'ĐANG TRANH ĐẤU'}</span><h2>${titles[room.settings.subject]}</h2></div><div class="pk-room-code"><small>MÃ PHÒNG</small><button data-pk-copy-code aria-label="Sao chép mã phòng">${room.code} ${icon('copy')}</button></div><button class="btn" data-pk-copy-link>Sao chép link</button><button class="btn" data-pk-leave>Rời phòng</button></div><div class="pk-room-grid"><div class="pk-main-column">${room.phase==='lobby'?`<section class="pk-glass pk-lobby">${roster()}<div class="pk-lobby-settings"><span>${room.total} câu</span><span>${room.settings.seconds} giây / câu</span><span>Tối đa 8 thành viên</span></div><div class="pk-ready-actions"><button class="btn ${mine.ready?'':'primary'}" data-pk-ready aria-pressed="${mine.ready}">${mine.ready?'Hủy sẵn sàng':'Tôi đã sẵn sàng'}</button>${room.host===user.id?`<button class="btn primary" data-pk-start ${room.players.filter(p=>!p.left).length<2?'disabled':''}>Bắt đầu tranh đấu ${icon('arrow')}</button>`:'<p>Chủ phòng sẽ bắt đầu khi tất cả sẵn sàng.</p>'}</div><p class="pk-help">Chia sẻ mã hoặc link cho bạn bè. Phòng tồn tại 12 giờ; người mất kết nối có thể vào lại bằng cùng hồ sơ.</p></section>`:room.phase==='playing'?quiz():results()}<section class="pk-room-etiquette">${icon('users')} Thi vui, học thật. Chat và voice dành cho nhóm bạn; không phải môi trường chống gian lận hay kỳ thi chính thức.</section></div><aside class="pk-social-column" aria-label="Trò chuyện cùng phòng">${voiceWidget()}${chat()}</aside></div>`;}
 function profileForm(){return `<section class="pk-glass pk-profile-form"><span class="pk-kicker">DẤU ẤN CỦA BẠN</span><h2>Để cả nhóm nhận ra bạn.</h2><p>Hồ sơ chỉ dùng trong bản thử này. Avatar và tên sẽ đồng bộ giữa các phòng bạn tham gia.</p><form id="pk-profile-form"><div class="pk-profile-preview">${avatar({id:user?.id||'preview',name:user?.name||'Bạn',avatar:profileAvatar},'large')}<label class="btn pk-upload">Chọn ảnh<input id="pk-avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><button class="btn" type="button" data-pk-remove-avatar>Bỏ ảnh</button></div><label for="pk-name">Tên hiển thị<input id="pk-name" name="name" minlength="2" maxlength="32" value="${esc(user?.name||'')}" placeholder="Tên mà bạn bè nhận ra" required autocomplete="nickname"></label><small>2–32 ký tự. Ảnh tối đa 10 MB, được cắt vuông và thu nhỏ trước khi gửi.</small><div class="pk-form-pair"><button class="btn primary" ${busy?'disabled':''}>Lưu hồ sơ thử</button><button class="btn" type="button" data-pk-profile-cancel>Quay lại</button></div></form></section>`;}
 function markup(){return `<section class="pk-page"><header class="pk-page-heading"><div><span class="pk-kicker">KIẾN HỌC / CÙNG NHAU THỬ SỨC</span><h1>${icon('swords')} Phòng tranh đấu</h1><p>Cạnh tranh một chút. Hiểu sâu thêm nhiều.</p></div><span class="pk-preview-tag">${window.PK_CONFIG.preview?'BẢN THỬ NGHIỆM':'HỌC CÙNG NHÓM'}</span></header><p id="pk-notice" class="pk-notice" role="status" ${error?'':'hidden'}>${esc(error)}</p><div id="pk-body">${profileOpen?profileForm():room&&user?roomView():landing()}</div></section>`;}
 function paint(){if(view!=='battle')return;const body=document.querySelector('#pk-body');if(!body)return;const active=document.activeElement,id=active?.id,start=active?.selectionStart;const messages=document.querySelector('#pk-messages'),atBottom=!messages||messages.scrollHeight-messages.scrollTop-messages.clientHeight<70,scroll=messages?.scrollTop;body.innerHTML=profileOpen?profileForm():room&&user?roomView():landing();notice(error);if(id){const next=document.getElementById(id);next?.focus({preventScroll:true});if(typeof start==='number'&&next?.setSelectionRange)next.setSelectionRange(start,start);}const log=document.querySelector('#pk-messages');if(log)log.scrollTop=atBottom?log.scrollHeight:scroll||0;window.KienCountUp?.mount(body);}
 function send(message){if(socket?.readyState===1){socket.send(JSON.stringify(message));return true;}notice('Đang kết nối lại. Chưa gửi thao tác; hãy chờ trạng thái trực tiếp.');return false;}
 async function joinRoom(next){if(!user){code=next;if(!window.PK_CONFIG.preview){window.openAuthModal();return;}profileOpen=true;paint();return;}busy=true;notice('');try{const result=await api('/'+next+'/ticket',{});room=result.state;clockOffset=room.now-Date.now();code=next;history.replaceState(null,'','#tranh-dau?room='+code);connect(result.ticket);paint();}catch(e){notice(e.message);}finally{busy=false;}}
 function connect(ticket){clearTimeout(reconnectTimer);const previous=socket;socket=null;if(previous){previous.onclose=null;previous.close();}const url=new URL(`/api/pk/${code}/socket`,location.origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';url.searchParams.set('ticket',ticket);const ws=socket=new WebSocket(url);ws.onopen=()=>{retries=0;notice('');paint();};ws.onmessage=e=>{if(socket!==ws)return;let m;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='state'){const oldRound=room?.round;room=m.state;clockOffset=room.now-Date.now();const mine=room.players.find(p=>p.id===user.id);if(!mine||mine.left){leaveRoom(false);notice('Bạn đã rời phòng này.');return;}voice.sync(room.players);paint();if(oldRound!==room.round&&view==='battle')document.querySelector('#pk-question-title')?.focus({preventScroll:true});}else if(m.type==='signal')voice.signal(m.from,m.payload);else if(m.type==='error')notice(m.error);};ws.onclose=e=>{if(socket!==ws)return;voice.leave();paint();if([1000,4001,4003,4004].includes(e.code)){if(e.code!==1000)notice(e.reason||'Phiên phòng đã đóng.');return;}notice('Mất kết nối. Đang tự vào lại phòng…');reconnectTimer=setTimeout(()=>joinRoom(code),Math.min(15000,1000*2**retries++));};ws.onerror=()=>notice('Kết nối phòng gián đoạn. Hệ thống đang thử lại.');}
 async function leaveRoom(explicit=true){clearTimeout(reconnectTimer);await voice.leave();if(explicit)send({type:'leave'});const ws=socket;socket=null;ws?.close(1000,'Rời phòng');room=null;code='';draft='';history.replaceState(null,'','#tranh-dau');paint();}
 function dock(){const nav=document.querySelector('.sidebar nav');if(nav&&!nav.querySelector('[data-pk-nav]')){const button=document.createElement('button');button.className='nav dock-item'+(view==='battle'?' active':'');button.type='button';button.dataset.pkNav='';button.innerHTML=`<span class="dock-icon tone-mint">${icon('swords')}</span><span>Phòng tranh đấu</span>`;nav.insertBefore(button,nav.querySelector('.dock-separator'));}nav?.querySelector('[data-pk-nav]')?.classList.toggle('active',view==='battle');}
 function open(){go('battle');history.replaceState(null,'',room?'#tranh-dau?room='+code:'#tranh-dau');}
 document.addEventListener('kien-auth-change',()=>{if(!window.PK_CONFIG.preview)api('/session').then(r=>{const previous=user?.id;user=r.user;if(previous&&previous!==user?.id)leaveRoom();else if(code&&user)joinRoom(code);paint();}).catch(()=>{});});
 document.addEventListener('kien-page-view',e=>{dock();if(e.detail.view==='battle')paint();else voice.leave();});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{if(b.hasAttribute('data-pk-nav')){open();return;}if(b.hasAttribute('data-pk-profile')){if(!window.PK_CONFIG.preview){window.openAuthModal(user?'profile':'email');return;}profileAvatar=user?.avatar||null;profileOpen=true;paint();}else if(b.hasAttribute('data-pk-profile-cancel')){profileOpen=false;paint();}else if(b.hasAttribute('data-pk-remove-avatar')){profileAvatar=null;const name=document.querySelector('#pk-name')?.value;paint();if(name)document.querySelector('#pk-name').value=name;}else if(b.hasAttribute('data-pk-ready')){const mine=room.players.find(p=>p.id===user.id);send({type:'ready',ready:!mine.ready});}else if(b.hasAttribute('data-pk-start'))send({type:'start'});else if(b.dataset.pkAnswer)send({type:'answer',round:room.round,choice:b.dataset.pkAnswer});else if(b.hasAttribute('data-pk-leave'))await leaveRoom();else if(b.dataset.pkKick){if(confirm('Mời thành viên này rời phòng?'))send({type:'kick',target:b.dataset.pkKick});}else if(b.hasAttribute('data-pk-rematch'))send({type:'rematch'});else if(b.hasAttribute('data-pk-copy-code')||b.hasAttribute('data-pk-copy-link')){const text=b.hasAttribute('data-pk-copy-code')?code:location.origin+'/#tranh-dau?room='+code;await navigator.clipboard.writeText(text);notice('Đã sao chép '+(text===code?'mã phòng.':'link mời.'));}else if(b.hasAttribute('data-pk-voice-expand')){voiceExpanded=!voiceExpanded;paint();}else if(b.hasAttribute('data-pk-voice-join')){await voice.join(code,user.id);paint();}else if(b.hasAttribute('data-pk-voice-leave')){await voice.leave();paint();}else if(b.hasAttribute('data-pk-mute')){voice.toggle();paint();}else if(b.hasAttribute('data-pk-listen'))voice.listen();}catch(err){notice(err.message||'Chưa thực hiện được.');}});
 document.addEventListener('input',e=>{if(e.target.id==='pk-message')draft=e.target.value;});
 document.addEventListener('change',async e=>{if(e.target.id!=='pk-avatar-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Chọn JPG, PNG hoặc WebP nhỏ hơn 10 MB.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,128,128);bitmap.close();profileAvatar=canvas.toDataURL('image/png');const name=document.querySelector('#pk-name')?.value;paint();if(name)document.querySelector('#pk-name').value=name;}catch(err){notice(err.message);}});
 document.addEventListener('submit',async e=>{const f=e.target;if(!['pk-create','pk-join','pk-chat-form','pk-profile-form'].includes(f.id))return;e.preventDefault();const data=new FormData(f);notice('');try{if(f.id==='pk-profile-form'){const result=await api('/session',{name:data.get('name'),avatar:profileAvatar});user=result.user;profileOpen=false;paint();if(code)await joinRoom(code);}else if(f.id==='pk-create'){if(busy)return;if(!user){if(!window.PK_CONFIG.preview){window.openAuthModal();return;}profileOpen=true;paint();return;}busy=true;const submit=f.querySelector('button');submit.disabled=true;let result;try{result=await api('/rooms',{subject:data.get('subject'),count:Number(data.get('count')),seconds:Number(data.get('seconds'))});}finally{busy=false;submit.disabled=false;}await joinRoom(result.code);}else if(f.id==='pk-join'){const next=String(data.get('code')).trim().toUpperCase();if(!/^[A-Z2-9]{6}$/.test(next))throw Error('Mã phòng gồm 6 chữ hoặc số.');await joinRoom(next);}else if(f.id==='pk-chat-form'){if(send({type:'chat',text:draft})){draft='';f.reset();}}}catch(err){notice(err.message);}});
 setInterval(()=>{if(document.hidden)return;const el=document.querySelector('#pk-time');if(el&&room?.phase==='playing'){const now=Date.now()+clockOffset,pre=now<room.roundStart;el.textContent=pre?'Bắt đầu sau '+Math.ceil((room.roundStart-now)/1000)+'s':Math.max(0,Math.ceil((room.deadline-now)/1000))+'s';for(const b of document.querySelectorAll('[data-pk-answer]'))b.disabled=!!room.myChoice||pre||now>=room.deadline;}},250);
 window.addEventListener('pagehide',()=>{voice.leave();socket?.close();});
 window.KienBattle={markup,open};dock();
 const initialRoom=location.hash.match(/^#tranh-dau(?:\?room=([A-Z2-9]{6}))?/i);if(initialRoom)open();
 api('/session').then(r=>{user=r.user;if(initialRoom?.[1])joinRoom(initialRoom[1].toUpperCase());else paint();}).catch(()=>notice('Không kết nối được dịch vụ phòng thử.'));
})();
